    [7334]={name="Efflorescent Robe",sourceType="quest_reward",instructions="Reward from the quest “Reception from Tyrande” — pick it over the other choices. In Stonetalon Mountains.",zone="Stonetalon Mountains",questName="Reception from Tyrande",lore="I am sure Tyrande Whisperwind herself would like to thank you for taking part in this mission. It may not appear so on the surface, but what you've helped start could very well strengthen our foothold in the Stonetalon Mountains."},
    [7344]={name="Torch of Holy Flame",sourceType="quest_reward",instructions="Reward from the quest “Morbent Fel”. In Duskwood.",zone="Duskwood",questName="Morbent Fel",lore="Morbent Fel hides in his lair, the house perched atop the hill to the east overlooking the Raven Hill cemetery. His time in this land is drawing to an end..."},
