    [11848]={name="Flax Belt",sourceType="quest_reward",instructions="Reward from the quest “Scavenging Deathknell” — pick it over the other choices. In Deathknell.",zone="Deathknell",questName="Scavenging Deathknell",lore="You there! If you're looking for something to make yourself useful, then listen up! We need fresh out-of-the-ground recruits to head into Deathknell and search for any sort of useful equipment."},
    [11855]={name="Tork Wrench",sourceType="quest_reward",instructions="Reward from the quest “Samophlange Manual” — pick it over the other choices. In The Barrens.",zone="The Barrens",questName="Samophlange Manual",lore="I think I can fix the samophlange, but I'm going to need the user's manual first."},
    [11865]={name="Rancor Boots",sourceType="quest_reward",instructions="Reward from the quest “Ribbly Screwspigot” — pick it over the other choices. In Blackrock Depths.",zone="Blackrock Depths",questName="Ribbly Screwspigot",lore="My brother Ribbly has always been a drain to his family, taking our money and wasting it on one scheme after another."},
    [11904]={name="Spirit of Aquementas",sourceType="quest_reward",instructions="Reward from the quest “It's Dangerous to Go Alone” — pick it over the other choices. In Un'Goro Crater.",zone="Un'Goro Crater",questName="It's Dangerous to Go Alone",lore="I finally remember now... I did come here to fight Blazerunner. I was on a journey, and this was to be the last step. But I am no longer the hero..."},
    [11924]={name="Robes of the Royal Crown",sourceType="boss_drop",instructions="Drops from Emperor Dagran Thaurissan in Blackrock Depths.",zone="Blackrock Depths",npc="Emperor Dagran Thaurissan",lore="Emperor of the Dark Iron, whose ancestor's summoning of Ragnaros doomed the clan. He took Moira Bronzebeard prisoner and she chose to stay."},
    [11935]={name="Magmus Stone",sourceType="boss_drop",instructions="Drops from Magmus in Blackrock Depths.",zone="Blackrock Depths",npc="Magmus"},
    [11936]={name="Relic Hunter Belt",sourceType="quest_reward",instructions="Reward from the quest “The Absent Minded Prospector” — pick it over the other choices. In Darkshore.",zone="Darkshore",questName="The Absent Minded Prospector",lore="So the prospector wants to send the mysterious fossil to the Explorers' League in Darnassus? I don't feel right leaving Darkshore without him."},
    [11962]={name="Manacle Cuffs",sourceType="quest_reward",instructions="Reward from the quest “The Love Potion” — pick it over the other choices. In Blackrock Depths.",zone="Blackrock Depths",questName="The Love Potion",lore="Oh, the pains of love! My dear Private Rocknot is immune to my charms. I am spurned! It's maddening! You must help me! We succubi know much of love, and I can make a potion to beat down the iron walls around Rocknot's heart."},
