    [15999]={name="Spellpower Goggles Xtreme Plus",sourceType="profession",instructions="Crafted with Engineering (requires skill 1).",profession="Engineering"},
    [16661]={name="Soft Willow Cape",sourceType="quest_reward",instructions="Reward from the quest “Je'neu of the Earthen Ring” — pick it over the other choices. In Ashenvale.",zone="Ashenvale",questName="Je'neu of the Earthen Ring",lore="The Earthen Ring is a shamanistic group dedicated to studying and preserving the elements. They have forgotten more about crazy old gods, ancient legends and lore than most scholars will ever know."},
    [16683]={name="Magister's Bindings",sourceType="boss_drop",instructions="Drops from Rage Talon Fire Tongue in Blackrock Spire.",zone="Blackrock Spire",npc="Rage Talon Fire Tongue"},
    [16789]={name="Captain Rackmore's Tiller",sourceType="quest_reward",instructions="Reward from the quest “Claim Rackmore's Treasure!”. In Desolace.",zone="Desolace",questName="Claim Rackmore's Treasure!",lore="Rackmore's log tells of how his ship was sailing for Feathermoon Stronghold when it was attacked by seafaring creatures."},
    [16887]={name="Witch's Finger",sourceType="quest_reward",instructions="Reward from the quest “Baron Aquanis” — pick it over the other choices. In Ashenvale.",zone="Ashenvale",questName="Baron Aquanis",lore="The defeated water elemental has left behind a strange water globe. You surmise that the object somehow fed the beast energy. Inside the globe, a putrid-looking form of water sloshes about."},
    [16894]={name="Clear Crystal Rod",sourceType="quest_reward",instructions="Reward from the quest “Arachnophobia” — pick it over the other choices. In Stonetalon Mountains.",zone="Stonetalon Mountains",questName="Arachnophobia",lore="Warning: Proceed into Sishir Canyon west of here at your own risk. Besseleth and her eight-legged children of the forest have claimed this canyon as their webbed lair."},
    [16975]={name="Warsong Sash",sourceType="quest_reward",instructions="Reward from the quest “Warsong Supplies” — pick it over the other choices. In Ashenvale.",zone="Ashenvale",questName="Warsong Supplies",lore="We are in short supply of a few items at the Warsong lumber camp!"},
    [16981]={name="Owlbeard Bracers",sourceType="quest_reward",instructions="Reward from the quest “Earthen Arise” — pick it over the other choices. In Stonetalon Mountains.",zone="Stonetalon Mountains",questName="Earthen Arise",lore="You have uncovered a dark threat to the land. The Resonite cask you have found in that cave houses a slumbering Earthen by the name of Goggeroc."},
    [17695]={name="Chestnut Mantle",sourceType="quest_reward",instructions="Reward from the quest “Allegiance to the Old Gods” — pick it over the other choices. In Blackfathom Deeps.",zone="Blackfathom Deeps",questName="Allegiance to the Old Gods",lore="This Twilight's Hammer follower cannot be allowed to complete his plan. The Twilight's Hammer do not understand the spirits of nature. They believe in the Old Gods--creatures of chaos and destruction that were long ago defeated."},
