    [19370]={name="Mantle of the Blackwing Cabal",sourceType="boss_drop",instructions="Drops from Razorgore the Untamed in Blackwing Lair.",zone="Blackwing Lair",npc="Razorgore the Untamed",lore="Set to guard the stolen dragon eggs. The raid takes control of the orb he is chained to and turns him on the clutch he was protecting."},
    [19375]={name="Mish'undare, Circlet of the Mind Flayer",sourceType="boss_drop",instructions="Drops from Nefarian.",npc="Nefarian",lore="Deathwing's son, working under Blackrock Mountain to breed the chromatic flight -- dragons carrying the blood of all five. He spent years in Stormwind's court as Lord Victor Nefarius while the work went on."},
    [19378]={name="Cloak of the Brood Lord",sourceType="boss_drop",instructions="Drops from Nefarian.",npc="Nefarian",lore="Deathwing's son, working under Blackrock Mountain to breed the chromatic flight -- dragons carrying the blood of all five. He spent years in Stormwind's court as Lord Victor Nefarius while the work went on."},
