    [19845]={name="Zandalar Illusionist's Mantle",sourceType="quest_reward",instructions="Reward from the quest “Paragons of Power: The Illusionist's Mantle”. In Zul'Gurub.",zone="Zul'Gurub",questName="Paragons of Power: The Illusionist's Mantle",lore="How can one truly hope to win against a foe that is not even really there? We Zandalar know the power of this, and as such illusionists hold a honored place within the tribe."},
    [19846]={name="Zandalar Illusionist's Wraps",sourceType="quest_reward",instructions="Reward from the quest “Paragons of Power: The Illusionist's Wraps”. In Zul'Gurub.",zone="Zul'Gurub",questName="Paragons of Power: The Illusionist's Wraps",lore="For you to know the way of our illusionists, go to Zul'Gurub and bring back to me selected Paragons of Power. For this, I will give you arm wraps our illusionists use to weave their spells."},
    [20037]={name="Arcane Crystal Pendant",sourceType="quest_reward",instructions="Reward from the quest “Destroy Morphaz” — pick it over the other choices.",questName="Destroy Morphaz",lore="Years ago, he overwhelmed me in a bold ambush and consumed my apprentice whole. While the loss of an apprentice is not unknown to me, this particular one carried an arcane shard of unsurpassed size and quality."},
